/**
 * Raster brand assets sourced from the official LANHC site (https://lanhc.com)
 * and embedded here so client bundles and desktop shells never fetch branding
 * at runtime. The Huayu emblem is the official full-color mark; the wordmark
 * mask is its alpha channel so consumers can recolor it with currentColor.
 */

/** Official 96px Huayu emblem tile as a PNG data URI. */
export const HUAYU_LOGO_DATA_URI = 'data:image/png;base64,' as const

/** Official 512px Huayu emblem tile as a PNG data URI (app icons, favicons). */
export const HUAYU_LOGO_512_DATA_URI = 'data:image/png;base64,' as const

/** Alpha mask of the official "Huayu AI" wordmark text as a PNG data URI. */
export const HUAYU_WORDMARK_MASK_DATA_URI = 'data:image/png;base64,' as const

/** Native viewBox of the official wordmark mask (width and height in user units). */
export const HUAYU_WORDMARK_VIEWBOX = { width: 670, height: 102 } as const
